class Solution {
  public String reformat(String s) {
    StringBuilder letters = new StringBuilder(), digits = new StringBuilder();
    for (char c : s.toCharArray())
      if (Character.isLetter(c)) letters.append(c);
      else digits.append(c);
    if (Math.abs(letters.length() - digits.length()) > 1) return "";
    StringBuilder out = new StringBuilder(s.length());
    boolean letterFirst = letters.length() >= digits.length();
    for (int i = 0, j = 0; i < letters.length() || j < digits.length(); ) {
      if (letterFirst && i < letters.length()) out.append(letters.charAt(i++));
      if (j < digits.length()) out.append(digits.charAt(j++));
      if (!letterFirst && i < letters.length()) out.append(letters.charAt(i++));
    }
    return out.toString();
  }
}
